#!/bin/zsh
query="$1"
item() { local title="$1" local subtitle="$2" local arg="$3" local valid="${4:-true}"
echo "{\"title\":\"$title\",\"subtitle\":\"$subtitle\",\"arg\":\"$arg\",\"valid\":$valid}" }
add_item() { items+=("$(item "$@")") }
items=()
if [[ "$query" == "up" || "$query" == "u" ]]; then add_item "Volume Up" "Increase volume by 10%" "u" elif [[ "$query" == "down" || "$query" == "d" ]]; then add_item "Volume Down" "Decrease volume by 10%" "d" elif [[ "$query" == "mute" || "$query" == "m" ]]; then add_item "Mute" "Mute Music/iTunes" "m" elif [[ "$query" == "unmute" || "$query" == "um" ]]; then add_item "Unmute" "Unmute Music/iTunes" "um" elif [[ "$query" =~ ^[0-9]+$ ]]; then local level=$((10#$query))
if (( level >= 0 && level <= 100 )); then add_item "Set Volume to ${level}%" "Define the volume percentage" "${level}" else add_item "Value out of range" "Volume must be between 0 and 100 (received: ${level})" "" "false" fi else add_item "Invalid input" "Use: up, down, mute, unmute, or 0-100" "" "false" fi
echo "{\"items\":[${(j:,:)items}]}"

#!/bin/zsh
# Ultra-optimized Music Volume Control Script # No input validation needed - handled by feedback.zsh
APP_NAME=Music
autoload is-at-least if ! is-at-least 10.15 $(sw_vers -productVersion); then APP_NAME=iTunes fi
set_volume() { local volume="$1" osascript -e "tell app \"$APP_NAME\" to set sound volume to $volume" >/dev/null echo "Current volume is ${volume}." }
get_volume() { osascript -e "tell app \"$APP_NAME\" to get sound volume" }
set_mute() { osascript -e "tell app \"$APP_NAME\" to set mute to true" >/dev/null echo "Muted." }
set_unmute() { osascript -e "tell app \"$APP_NAME\" to set mute to false" >/dev/null echo "Unmuted." }
# Direct argument parsing (from feedback.zsh args) case "$1" in "u") volume=$(get_volume) volume=$((volume + 10)) ((volume > 100)) && volume=100 set_volume "$volume" ;; "d") volume=$(get_volume) volume=$((volume - 10)) ((volume < 0)) && volume=0 set_volume "$volume" ;; "m") set_mute ;; "um") set_unmute ;; [0-9]*) volume="$1" ((volume > 100)) && volume=100 set_volume "$volume" ;; *) volume=$(get_volume) echo "Current volume is ${volume}." ;; esac
